<script setup lang="ts">
import DemoPlanBoard from './DemoPlanBoard.vue'
import DemoReferences from './DemoReferences.vue'
import type {DashboardTarget} from '../domain/dashboard'
import DemoFollowups from './DemoFollowups.vue'
import DemoRetryPanel from './DemoRetryPanel.vue'
import {computed,onMounted,onUnmounted,ref,toRaw,nextTick} from 'vue'
import {demoAgenda,demoCriteria,demoAction,demoElapsed,demoText,demoReview,emptyDemo,newDemo,parseDemo,demoRetry,type DemoBackup,type DemoSession} from '../domain/demo'
import {loadDemo,saveDemo} from '../demo-storage'
const props=defineProps<{initialTarget?:DashboardTarget}>(),dataSection=ref<HTMLElement>(),planSection=ref<HTMLElement>()
const data=ref(emptyDemo()),ready=ref(false),failed=ref(false),busy=ref(false),message=ref(''),selected=ref(''),title=ref(''),text=ref(''),quote=ref(''),next=ref(''),criterion=ref<'role'|'tradeoff'|'outcome'>('role'),now=ref(Date.now())
const current=computed(()=>data.value.sessions.find(s=>s.id===selected.value)),active=computed(()=>data.value.sessions.find(s=>s.status!=='DONE'))
const used=computed(()=>current.value?demoElapsed(current.value,now.value):0)
const clock=setInterval(()=>{now.value=Date.now()},250)
onUnmounted(()=>clearInterval(clock))
onMounted(async()=>{try{data.value=await loadDemo();const target=props.initialTarget;if(target?.kind==='DEMO_SESSION'){if(data.value.sessions.some(s=>s.id===target.id))open(target.id);else{open('');message.value='Lượt Demo đã bị xóa hoặc thay thế; hãy chọn lượt hiện có.'}}else open(active.value?.id??data.value.sessions[0]?.id??'')}catch{failed.value=true;message.value='Không đọc được Demo. Ghi mới bị khóa; hãy khôi phục backup.'}finally{ready.value=true;await nextTick();if(props.initialTarget?.kind==='DEMO_PLAN')planSection.value?.scrollIntoView({block:'start'});if(props.initialTarget?.kind==='DEMO_DATA')dataSection.value?.scrollIntoView({block:'start'})}})
function open(id:string){selected.value=id;text.value=current.value?.text??'';quote.value='';next.value=''}
async function commit(value:DemoBackup){busy.value=true;message.value='';try{await saveDemo(value);data.value=value;failed.value=false;message.value='Đã lưu Demo trên thiết bị.';return true}catch{message.value='Không lưu được Demo. Bản đã lưu được giữ nguyên.';return false}finally{busy.value=false}}
async function replace(s:DemoSession){return commit({...toRaw(data.value),sessions:data.value.sessions.map(v=>v.id===s.id?s:toRaw(v))})}
async function start(){try{if(active.value||failed.value||data.value.sessions.length>=50)return;const s=newDemo(title.value,Date.now());if(await commit({...toRaw(data.value),sessions:[s,...toRaw(data.value.sessions)]})){open(s.id);title.value=''}}catch{message.value='Nhập tên dự án từ 1 đến 120 ký tự.'}}
async function retry(mode:'GUIDED'|'INDEPENDENT'){if(!current.value||busy.value)return;try{const value=demoRetry(toRaw(data.value),current.value.id,mode,Date.now());if(await commit(value))open(value.sessions[0]!.id)}catch{message.value='Hoàn tất nội dung và ba câu phản biện; không có lượt đang chạy, tối đa 50 lượt.'}}
async function action(a:'pause'|'resume'|'split'|'finish'){if(!current.value)return;try{if(a==='finish'&&!window.confirm('Kết thúc lượt demo và chuyển sang ghi nội dung/review?'))return;await replace(demoAction(toRaw(current.value),a,Date.now()))}catch{message.value='Không thể thực hiện thao tác.'}}
async function saveText(){if(!current.value)return;try{if(text.value!==current.value.text&&current.value.reviews.length&&!window.confirm('Sửa nội dung sẽ xóa review bài trình bày và đánh dấu các trả lời phản biện lỗi thời. Tiếp tục?'))return;await replace(demoText(toRaw(current.value),text.value))}catch{message.value='Nội dung không hợp lệ (tối đa 20.000 ký tự).'}}
async function review(){if(!current.value)return;try{if(await replace(demoReview(toRaw(current.value),criterion.value,quote.value,next.value))){quote.value='';next.value=''}}catch{message.value='Trích dẫn phải khớp nguyên văn nội dung đã lưu; trích dẫn và hướng sửa từ 1 đến 2.000 ký tự.'}}
function format(ms:number){const s=Math.floor(ms/1000);return `${Math.floor(s/60).toString().padStart(2,'0')}:${(s%60).toString().padStart(2,'0')}`}
function download(){const url=URL.createObjectURL(new Blob([JSON.stringify(data.value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='brse-demo.json';a.click();URL.revokeObjectURL(url)}
async function upload(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>5_000_000)throw Error();const value=parseDemo(await file.text());if(window.confirm('Thay thế toàn bộ Demo trên thiết bị, kể cả lượt đang chạy?'))if(await commit(value))open(value.sessions.find(s=>s.status!=='DONE')?.id??value.sessions[0]?.id??'')}catch{message.value='Backup Demo không hợp lệ; dữ liệu không bị thay thế.'}finally{input.value=''}}
async function clear(){if(window.confirm('Xóa toàn bộ Demo? Hãy xuất backup trước nếu cần giữ.'))if(await commit(emptyDemo()))open('')}
</script>
<template>
 <div class="eyebrow">PROJECT DEMO · LUYỆN LOCAL</div><h1 class="page-title">Trình bày dự án trong 10 phút</h1><p class="lead">Bối cảnh → vai trò → kiến trúc → tính năng → thách thức → kết quả.</p>
 <div class="notice">Agenda tự biên soạn, chưa hiệu chuẩn. Timer tiếp tục khi rời màn hình; reload dựa trên đồng hồ thiết bị, có thể sai nếu đổi giờ. Không ghi âm, không gửi repo/CV hay nội dung đến AI. Tự review không phải đánh giá tuyển dụng.</div>
 <p v-if="message" role="status">{{message}}</p><p v-if="!ready">Đang mở Demo…</p>
 <template v-if="ready"><section class="card form-card"><h2>Bắt đầu lượt mới</h2><form @submit.prevent="start"><label>Tên dự án demo<input v-model="title" maxlength="120" :disabled="busy||failed||!!active"></label><button class="primary" :disabled="busy||failed||!!active||data.sessions.length>=50">Bắt đầu demo</button></form><p class="hint">Tối đa 50 lượt. {{active?'Hoàn tất lượt đang luyện trước khi tạo lượt mới.':''}}</p><button v-if="active&&selected!==active.id" @click="open(active.id)">Tiếp tục Demo đang luyện</button></section>
 <section v-if="current" class="card form-card"><h2>{{current.title}}</h2><p>{{current.status}} · {{new Date(current.createdAt).toLocaleString('vi-VN')}}</p><div class="timer" role="timer" aria-label="Thời gian demo đã dùng">{{format(used)}}</div><p>{{used>=600000?'Đã tới/vượt mốc 10 phút — chủ động kết thúc khi trình bày xong.':'Mục tiêu 10:00 · không tự kết thúc hoặc chấm điểm.'}}</p>
 <ol><li v-for="(part,i) in demoAgenda" :key="part.title"><strong>{{part.title}}</strong> · dự kiến {{part.seconds/60}} phút <span v-if="i<current.splits.length"> · thực tế {{format(current.splits[i]!-(i?current.splits[i-1]!:0))}}</span><span v-else-if="i===current.splits.length&&current.status!=='DONE'"> ← đang trình bày</span><span v-else-if="i===current.splits.length&&current.status==='DONE'"> · thực tế {{format(current.elapsedMs-(i?current.splits[i-1]!:0))}}</span><span v-else-if="current.status==='DONE'"> · chưa ghi mốc</span></li></ol>
 <div class="actions"><button v-if="current.status==='RUNNING'" :disabled="busy" @click="action('pause')">Tạm dừng Demo</button><button v-if="current.status==='PAUSED'" :disabled="busy" @click="action('resume')">Tiếp tục bấm giờ Demo</button><button v-if="current.status==='RUNNING'&&current.splits.length<5" :disabled="busy" @click="action('split')">Sang mục tiếp theo</button><button v-if="current.status!=='DONE'" :disabled="busy" @click="action('finish')">Kết thúc Demo</button></div>
 <template v-if="current.status==='DONE'"><form @submit.prevent="saveText"><label>Nội dung trình bày tự ghi<textarea v-model="text" maxlength="20000" :disabled="busy"></textarea></label><p class="hint">Nhập nội dung bạn đã trình bày hoặc ghi chú sau luyện; đây không phải transcript được ghi âm/xác thực. Sửa nội dung sẽ xóa review bài trình bày và đánh dấu các trả lời phản biện lỗi thời.</p><button :disabled="busy">Lưu nội dung Demo</button></form><h3>Tự review bằng chứng · demo-self-v1</h3><p>Chỉ trích dẫn text đã lưu, không suy ra timestamp audio hoặc điểm AI.</p><ul><li v-for="c in demoCriteria" :key="c.id"><strong>{{c.title}}</strong>: {{c.prompt}}</li></ul>
 <form @submit.prevent="review"><label>Tiêu chí Demo<select v-model="criterion"><option v-for="c in demoCriteria" :key="c.id" :value="c.id">{{c.title}}</option></select></label><label>Trích dẫn Demo nguyên văn<textarea v-model="quote" maxlength="2000"></textarea></label><label>Hướng sửa lần tới<textarea v-model="next" maxlength="2000"></textarea></label><button :disabled="busy||text!==current.text">Lưu tự review Demo</button></form><p v-if="text!==current.text" class="hint">Lưu nội dung trước khi review.</p>
 <article v-for="r in current.reviews" :key="r.criterion" class="notice"><strong>{{demoCriteria.find(c=>c.id===r.criterion)?.title}} · SELF_REVIEW · v{{r.version}}</strong><blockquote>{{r.quote}}</blockquote><p>{{r.next}}</p></article></template></section>
 <DemoReferences v-if="current" :session="current" :busy="busy" @change="replace"/>
 <DemoFollowups v-if="current?.status==='DONE'" :session="current" :busy="busy" @change="replace"/>
 <DemoRetryPanel v-if="current" :session="current" :parent="data.sessions.find(s=>s.id===current?.retry?.parentId)" :blocked="busy||!!active||data.sessions.length>=50" @retry="retry"/>
 <div ref="planSection"><DemoPlanBoard :data="data" :current="current" :busy="busy||failed" @change="commit" @open="open"/></div>
 <section class="card form-card"><h2>Lịch sử Demo ({{data.sessions.length}})</h2><p v-if="!data.sessions.length">Chưa có lượt demo.</p><div v-for="s in data.sessions" :key="s.id" class="actions"><button :disabled="busy" @click="open(s.id)">{{s.title}} · {{s.status}} · {{s.reviews.length}}/3 tự review</button></div></section>
 <section ref="dataSection" class="card form-card"><h2>Dữ liệu Demo riêng</h2><p>JSON chưa mã hóa, chỉ chứa Demo. Không dùng nội dung dự án mật. Nhập thay thế module này; không ảnh hưởng Exam, Interview hay Sổ từ.</p><div class="actions"><button :disabled="busy||failed" @click="download">Xuất Demo JSON</button><label class="file-button">Nhập Demo JSON<input type="file" accept=".json,application/json" :disabled="busy" @change="upload"></label><button :disabled="busy||failed" @click="clear">Xóa dữ liệu Demo</button></div></section></template>
</template>
<style scoped>textarea{width:100%;min-height:95px;box-sizing:border-box}li{margin:12px 0}blockquote{white-space:pre-wrap;overflow-wrap:anywhere}h2,button{overflow-wrap:anywhere}</style>
